#!/usr/bin/env python3
"""sen0401_lineage_cancel_ch13rebuild v1_0_0 - closes ST_Ch13_PageRebuild (the chapter 13 page 9.82.0) with its Build (Suspended) and Verify (Ready) tasks as CANCELLED, superseded by ST_Ch13_PageRebuild2 (page 9.83.0, controlled Done in v0.573.0). The owner's rule on cancelling is applied: an as-is fit-gap and impact analysis (accomplished, failed, in progress, due; an ImpactAssessment) and a closure report marked CANCELLED (a ClosureReport) are recorded in the SAME version as the cancellation, before it. Criteria are not edited, not waived. Usage: no arguments; one new register version."""
__version__ = "1.0.0"
import os, re, sys, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0401_lineage_succession_v1_1_0 as M
import sen0401_lineage_succession3_v1_1_0 as X
import sen0401_lineage_template_revision_v1_0_0 as T
import sen0401_lineage_control_v1_0_0 as C
lit = C.lit
src = M.newest(); t = open(src, encoding="utf-8").read(); nxt, cur = M.next_version(src); L = []; now = M.now()
_i, _j = T.blk(t, "TK_Ch13_PageRebuild2_Verify"); assert "hasState backlog:Done" in t[_i:_j]
FITGAP = ("AS-IS FIT-GAP AND IMPACT ANALYSIS of ex:ST_Ch13_PageRebuild (read from the register v%s and the control of 2026-10-27, v0.560.0; criterion AC9_PageRebuild_Ch13). "
          "ACCOMPLISHED (met, measured by the control): the page 9.82.0 exists as a new file (commit f8983f3) built from the deck 2.3.0, the manifest v1_2_0 and the template 9.52.5; the page test 9.37.0 now exits 0 (392 passed, 0 failed), the example 12 defect of 9.81.0 is gone; 9.34.1 and 9.35.1 exit 0; charset; story layout probe 12 of 12; ERD collision CLEAR; chapter-code tab equals the manifest (28 examples); Stage 4 gates; Research, Deck and Page chapter checks; deck match 0 not carried; deck hyperlinks carried; nochange over its six commits; the page ABox and the stored result as new files. "
          "FAILED (measured): element (2) of the criterion, no skip: each of the three page tests printed two [SKIP] lines (the filled ERD reading and the on-choice labels mode) because the research of chapter 13 stated no relationship between two sections (change request ex:CR3_Ch13Links). "
          "IN PROGRESS: nothing; the Build task is Suspended since the control and its Verify task was never started. "
          "DUE: nothing on this unit: what it was to deliver (a chapter 13 page that meets AC9_PageRebuild_Ch13) is delivered by ex:ST_Ch13_PageRebuild2 (the page 9.83.0 on the research v1_1_0, controlled MET in v0.573.0 with 0 skips, 394/370/370 passed). "
          "IMPACT of the cancellation: the page file 9.82.0 and its commits stay in the repository, unchanged (nothing is deleted or edited); the criterion AC9_PageRebuild_Ch13 is not edited and not waived: it stays on the register as the criterion this unit did not meet, and the same measures, with the no-skip element made explicit, are met by AC9_PageRebuild2_Ch13; no other item depends on these three (checked: the only dependency is the Verify task on its own Build task); the open-story ranking loses one entry and no other score changes; the mission's coverage is unaffected (the chapter 13 page is delivered by the second rebuild).")
for tk in ("TK_Ch13_PageRebuild_Verify", "TK_Ch13_PageRebuild_Build", "ST_Ch13_PageRebuild"):
    i, j = T.blk(t, tk); b = t[i:j]; m = re.search(r"backlog:hasState backlog:(Proposed|Ready|InProgress|Suspended)\b", b); assert m, tk
L.append('\nex:IA3_Ch13RebuildCancel a backlog:ImpactAssessment ;\n    rdfs:label "As-is fit-gap and impact of cancelling the chapter 13 page 9.82.0 story"@en ;\n    backlog:analyzesRequest ex:CR3_Ch13Links ; backlog:identifiesAffectedLineage ex:Lineage3 ;\n    backlog:hasImpactStatement %s .\n' % lit(FITGAP % cur))
L.append('\nex:ClosureRep3_Ch13Rebuild a backlog:ClosureReport ;\n    rdfs:label "Closure report of the chapter 13 page 9.82.0 story: CANCELLED (superseded)"@en ; backlog:belongsToLineage ex:Lineage3 ;\n    backlog:reportGeneratedAt "%s"^^xsd:dateTime ; rdfs:seeAlso ex:ST_Ch13_PageRebuild, ex:IA3_Ch13RebuildCancel, ex:ST_Ch13_PageRebuild ;\n    backlog:hasClosureSummary %s .\n' % (now, lit("CLOSURE STATUS: CANCELLED (not Done, not failed-and-forgotten). The story ex:ST_Ch13_PageRebuild with its tasks TK_Ch13_PageRebuild_Build (was Suspended) and TK_Ch13_PageRebuild_Verify (was Proposed) is cancelled on " + now + " UTC because its deliverable was superseded by ex:ST_Ch13_PageRebuild (the chapter 13 page 9.80.0 on the template 9.52.5, controlled Done). The unit itself did not meet its criterion (page tests failed, see the analysis ex:IA3_Ch13RebuildCancel); that is kept as the record and is not waived. The failed page stays in the repository unchanged. Lessons: an expected output that begins with a message prefix can fail a page that is otherwise correct, and a chapter whose research states no relationship between two sections skips the ERD label features; both are now measured before a page is built.")))
for tk in ("TK_Ch13_PageRebuild_Verify", "TK_Ch13_PageRebuild_Build", "ST_Ch13_PageRebuild"):
    i, j = T.blk(t, tk); b = t[i:j]; m = re.search(r"backlog:hasState backlog:(Proposed|Ready|InProgress|Suspended)\b", b); frm = m.group(1)
    why = "Cancelled %s UTC (v%s): superseded by ex:ST_Ch13_PageRebuild2 (page 9.83.0, controlled Done); the unit's own criterion was not fully met (element 2, no skip: two [SKIP] lines per page test; see ex:IA3_Ch13RebuildCancel and ex:ClosureRep3_Ch13Rebuild, status CANCELLED). Criteria not edited, not waived." % (now, nxt)
    nb = b.replace(m.group(0), "backlog:hasState backlog:Cancelled", 1)
    nb = re.sub(r'backlog:hasRationale "(?:[^"\\]|\\.)*"', lambda _: "backlog:hasRationale " + lit(why), nb, count=1) if "backlog:hasRationale" in nb else nb.replace("backlog:hasState backlog:Cancelled", "backlog:hasState backlog:Cancelled ; backlog:hasRationale " + lit(why), 1)
    nb = re.sub(r'backlog:lastAuditedAt "[^"]*"', 'backlog:lastAuditedAt "%s"' % now, nb, count=1) if "lastAuditedAt" in nb else nb
    t = t[:i] + nb + t[j:]; time.sleep(1.1); at = M.now(); L.append(C.transition("Cx13r_" + tk, tk, "T_Withdraw" + frm, at, why, tk + " cancelled"))
print(os.path.basename(M.write_new(src, X.set_status(t + "\n" + "".join(L), "LS_InProgress"), nxt, cur, "ST_Ch13_PageRebuild and its tasks cancelled (superseded by ST_Ch13_PageRebuild) with an as-is fit-gap and impact analysis and a closure report marked CANCELLED.")))
